with a as(select * from public.authors where open_library_id=any(array['OL57758A','OL792251A','OL29542A','OL138536A','OL151894A','OL88537A','OL187319A','OL200233A']::text[]) or id=any(array[654,3197,2613,704,701,2776,905,669]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789029518697','9789020409482','9789022565407','9789023666905','9789063250553','9789028205871','9789023666486','9789025402266','9789060698600','9789047701699','9789060697757']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL719956W','OL10587374W','OL108934W','OL1355519W','OL1447283W','OL14904098W','OL14904141W','OL1667577W','OL1736486W','OL1736488W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['mammoetopzondag','thegardenofweapons','dewapentuin','angeltherapy','gesprekkenmetengelen','dedoopvont','johannesviator','bijnaderinzien','apollyon','hedenik','destommevankampen','hetgeheimvanrotterdam']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['mammoetopzondag','thegardenofweapons','dewapentuin','angeltherapy','gesprekkenmetengelen','dedoopvont','johannesviator','bijnaderinzien','apollyon','hedenik','destommevankampen','hetgeheimvanrotterdam']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987140001 and 987140999),'editions',(select count(*) from public.editions where id between 987240001 and 987240999),'authors',(select count(*) from public.authors where id between 987340001 and 987340999))) as preflight;
